[metadata] {"type": "create", "filePath": "/app/output/styles.css", "content": "/* ============================================
   WellStream Platform — Design System
   ============================================ */

@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800&display=swap');

/* --- Reset & Base --- */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --bg-primary: #0D1B2A;
  --bg-secondary: #1B2838;
  --bg-card: #1E3048;
  --bg-card-hover: #243A54;
  --bg-input: #152238;
  --accent-blue: #00B4D8;
  --accent-teal: #0077B6;
  --accent-green: #6CC24A;
  --accent-gradient: linear-gradient(135deg, #0077B6, #00B4D8);
  --text-primary: #FFFFFF;
  --text-secondary: #B0BEC5;
  --text-muted: #78909C;
  --border-color: #2A3F5F;
  --border-light: #1E3A5F;
  --shadow-card: 0 4px 24px rgba(0,0,0,0.3);
  --shadow-elevated: 0 8px 40px rgba(0,0,0,0.4);
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --radius-full: 9999px;
  --transition: 0.25s ease;
  --container: 1200px;
  --section-pad: 80px;
}

html { scroll-behavior: smooth; }

body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  background: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

a { color: var(--accent-blue); text-decoration: none; transition: color var(--transition); }
a:hover { color: var(--accent-teal); }

img { max-width: 100%; display: block; }

.container {
  max-width: var(--container);
  margin: 0 auto;
  padding: 0 24px;
}

/* --- Header / Navigation --- */
.site-header {
  position: fixed;
  top: 0; left: 0; right: 0;
  z-index: 1000;
  background: rgba(13,27,42,0.95);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border-color);
  height: 72px;
}

.header-inner {
  max-width: var(--container);
  margin: 0 auto;
  padding: 0 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 100%;
}

.logo {
  font-size: 22px;
  font-weight: 800;
  color: var(--text-primary);
  letter-spacing: -0.5px;
  display: flex;
  align-items: center;
  gap: 8px;
}
.logo span { color: var(--accent-blue); }

.nav { display: flex; align-items: center; gap: 8px; }

.nav-link {
  color: var(--text-secondary);
  font-size: 14px;
  font-weight: 500;
  padding: 8px 16px;
  border-radius: var(--radius-sm);
  transition: all var(--transition);
  position: relative;
}
.nav-link:hover { color: var(--text-primary); background: rgba(255,255,255,0.05); }

/* Platform dropdown */
.nav-dropdown { position: relative; }
.nav-dropdown .dropdown-menu {
  position: absolute;
  top: calc(100% + 8px);
  left: 0;
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 8px;
  min-width: 220px;
  box-shadow: var(--shadow-elevated);
  opacity: 0;
  visibility: hidden;
  transform: translateY(-8px);
  transition: all var(--transition);
}
.nav-dropdown:hover .dropdown-menu,
.nav-dropdown.active .dropdown-menu {
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
}
.dropdown-menu a {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 14px;
  color: var(--text-secondary);
  font-size: 14px;
  border-radius: var(--radius-sm);
  transition: all var(--transition);
}
.dropdown-menu a:hover { background: rgba(0,180,216,0.1); color: var(--accent-blue); }
.dropdown-menu a .dd-icon {
  width: 32px; height: 32px;
  display: flex; align-items: center; justify-content: center;
  background: rgba(0,180,216,0.1);
  border-radius: var(--radius-sm);
  font-size: 14px;
  flex-shrink: 0;
}

.btn-demo {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: var(--accent-gradient);
  color: #fff;
  font-size: 14px;
  font-weight: 600;
  padding: 10px 22px;
  border-radius: var(--radius-full);
  border: none;
  cursor: pointer;
  transition: all var(--transition);
  text-decoration: none;
  white-space: nowrap;
}
.btn-demo:hover { transform: translateY(-1px); box-shadow: 0 4px 16px rgba(0,180,216,0.4); color: #fff; }

/* Mobile menu toggle */
.menu-toggle {
  display: none;
  background: none;
  border: none;
  color: var(--text-primary);
  font-size: 24px;
  cursor: pointer;
  padding: 8px;
}

/* --- Hero --- */
.hero {
  padding: 140px 0 var(--section-pad);
  position: relative;
  overflow: hidden;
}
.hero::before {
  content: '';
  position: absolute;
  top: -200px; right: -200px;
  width: 600px; height: 600px;
  background: radial-gradient(circle, rgba(0,180,216,0.08) 0%, transparent 70%);
  pointer-events: none;
}
.hero::after {
  content: '';
  position: absolute;
  bottom: -100px; left: -100px;
  width: 400px; height: 400px;
  background: radial-gradient(circle, rgba(0,119,182,0.06) 0%, transparent 70%);
  pointer-events: none;
}
.hero-label {
  display: inline-block;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--accent-blue);
  background: rgba(0,180,216,0.1);
  padding: 6px 16px;
  border-radius: var(--radius-full);
  margin-bottom: 24px;
}
.hero h1 {
  font-size: 52px;
  font-weight: 800;
  line-height: 1.1;
  letter-spacing: -1.5px;
  max-width: 800px;
  margin-bottom: 20px;
}
.hero h1 .highlight { color: var(--accent-blue); }
.hero p {
  font-size: 18px;
  color: var(--text-secondary);
  max-width: 600px;
  margin-bottom: 32px;
  line-height: 1.7;
}
.hero-actions { display: flex; gap: 16px; flex-wrap: wrap; }

/* --- Buttons --- */
.btn-primary {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: var(--accent-gradient);
  color: #fff;
  font-size: 15px;
  font-weight: 600;
  padding: 14px 28px;
  border-radius: var(--radius-full);
  border: none;
  cursor: pointer;
  transition: all var(--transition);
  text-decoration: none;
}
.btn-primary:hover { transform: translateY(-2px); box-shadow: 0 6px 24px rgba(0,180,216,0.4); color: #fff; }

.btn-secondary {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: transparent;
  color: var(--text-primary);
  font-size: 15px;
  font-weight: 600;
  padding: 14px 28px;
  border-radius: var(--radius-full);
  border: 1px solid var(--border-color);
  cursor: pointer;
  transition: all var(--transition);
  text-decoration: none;
}
.btn-secondary:hover { border-color: var(--accent-blue); color: var(--accent-blue); }

/* --- Section utilities --- */
.section { padding: var(--section-pad) 0; }
.section-alt { background: var(--bg-secondary); }

.section-label {
  display: inline-block;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--accent-blue);
  margin-bottom: 12px;
}
.section-title {
  font-size: 36px;
  font-weight: 700;
  letter-spacing: -0.5px;
  line-height: 1.2;
  margin-bottom: 16px;
}
.section-subtitle {
  font-size: 16px;
  color: var(--text-secondary);
  max-width: 600px;
  line-height: 1.7;
}

/* --- Tabs --- */
.tabs {
  display: flex;
  gap: 4px;
  background: rgba(255,255,255,0.04);
  padding: 4px;
  border-radius: var(--radius-full);
  margin-bottom: 40px;
  flex-wrap: wrap;
}
.tab-btn {
  padding: 10px 24px;
  font-size: 14px;
  font-weight: 600;
  color: var(--text-secondary);
  background: transparent;
  border: none;
  border-radius: var(--radius-full);
  cursor: pointer;
  transition: all var(--transition);
  white-space: nowrap;
}
.tab-btn:hover { color: var(--text-primary); }
.tab-btn.active {
  background: var(--accent-gradient);
  color: #fff;
  box-shadow: 0 2px 8px rgba(0,180,216,0.3);
}
.tab-panel { display: none; animation: fadeIn 0.3s ease; }
.tab-panel.active { display: block; }

@keyframes fadeIn { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: translateY(0); } }

/* --- Cards --- */
.card-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}
.card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 32px;
  transition: all var(--transition);
}
.card:hover {
  border-color: var(--accent-blue);
  box-shadow: var(--shadow-card);
  transform: translateY(-4px);
}
.card-icon {
  width: 48px; height: 48px;
  display: flex; align-items: center; justify-content: center;
  background: rgba(0,180,216,0.1);
  border-radius: var(--radius-md);
  font-size: 22px;
  margin-bottom: 20px;
  color: var(--accent-blue);
}
.card h3 {
  font-size: 18px;
  font-weight: 700;
  margin-bottom: 10px;
}
.card p {
  font-size: 14px;
  color: var(--text-secondary);
  line-height: 1.6;
}

/* --- Featured Banner --- */
.featured-banner {
  background: var(--accent-gradient);
  border-radius: var(--radius-lg);
  padding: 40px 48px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 32px;
  margin: 0 auto;
  max-width: var(--container);
  position: relative;
  overflow: hidden;
}
.featured-banner::before {
  content: '';
  position: absolute;
  top: -50px; right: -50px;
  width: 200px; height: 200px;
  background: rgba(255,255,255,0.08);
  border-radius: 50%;
}
.featured-banner .banner-label {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 2px;
  text-transform: uppercase;
  opacity: 0.8;
  margin-bottom: 4px;
}
.featured-banner h3 {
  font-size: 28px;
  font-weight: 800;
  margin-bottom: 4px;
}
.featured-banner .banner-tagline {
  font-size: 16px;
  opacity: 0.9;
}
.featured-banner .btn-banner {
  background: rgba(255,255,255,0.15);
  color: #fff;
  font-weight: 600;
  padding: 12px 28px;
  border-radius: var(--radius-full);
  border: 1px solid rgba(255,255,255,0.3);
  cursor: pointer;
  transition: all var(--transition);
  text-decoration: none;
  white-space: nowrap;
}
.featured-banner .btn-banner:hover { background: rgba(255,255,255,0.25); }

/* --- Stats --- */
.stats-row {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
}
.stat-item { text-align: center; }
.stat-circle {
  width: 160px; height: 160px;
  border-radius: 50%;
  margin: 0 auto 20px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  position: relative;
}
.stat-circle svg {
  position: absolute;
  top: 0; left: 0;
  width: 100%; height: 100%;
  transform: rotate(-90deg);
}
.stat-circle .stat-value {
  font-size: 40px;
  font-weight: 800;
  color: var(--accent-blue);
  line-height: 1;
}
.stat-circle .stat-unit {
  font-size: 14px;
  font-weight: 600;
  color: var(--accent-blue);
}
.stat-label {
  font-size: 14px;
  color: var(--text-secondary);
  max-width: 200px;
  margin: 0 auto;
  line-height: 1.5;
}

/* --- Timeline --- */
.timeline { max-width: 700px; margin: 0 auto; }
.timeline-item {
  display: flex;
  align-items: flex-start;
  gap: 24px;
  margin-bottom: 36px;
}
.timeline-duration {
  min-width: 120px;
  text-align: right;
  padding-top: 4px;
}
.timeline-duration .dur-value {
  font-size: 24px;
  font-weight: 800;
  color: var(--accent-blue);
}
.timeline-duration .dur-label {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--text-muted);
}
.timeline-bar {
  flex: 1;
  padding-top: 10px;
}
.progress-track {
  width: 100%;
  height: 8px;
  background: var(--bg-card);
  border-radius: var(--radius-full);
  overflow: hidden;
}
.progress-fill {
  height: 100%;
  background: var(--accent-gradient);
  border-radius: var(--radius-full);
  transition: width 1s ease;
}
.timeline-desc {
  font-size: 14px;
  color: var(--text-secondary);
  margin-top: 6px;
}

/* --- Accordion --- */
.accordion { max-width: 800px; margin: 0 auto; }
.accordion-item {
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  margin-bottom: 12px;
  overflow: hidden;
  transition: border-color var(--transition);
}
.accordion-item.open { border-color: var(--accent-blue); }
.accordion-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 20px 24px;
  background: var(--bg-card);
  cursor: pointer;
  transition: background var(--transition);
  border: none;
  width: 100%;
  text-align: left;
  color: var(--text-primary);
  font-size: 16px;
  font-weight: 700;
  font-family: inherit;
}
.accordion-header:hover { background: var(--bg-card-hover); }
.accordion-header .acc-icon {
  width: 24px; height: 24px;
  display: flex; align-items: center; justify-content: center;
  transition: transform var(--transition);
  color: var(--accent-blue);
  font-size: 18px;
}
.accordion-item.open .acc-icon { transform: rotate(45deg); }
.accordion-body {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.35s ease;
}
.accordion-body-inner {
  padding: 0 24px 20px;
  font-size: 14px;
  color: var(--text-secondary);
  line-height: 1.7;
  background: var(--bg-card);
}

/* --- Diagrams --- */
.diagram-container {
  max-width: 900px;
  margin: 0 auto;
  padding: 40px 0;
}

/* Platform ecosystem diagram */
.ecosystem-diagram {
  display: flex;
  justify-content: center;
  gap: 32px;
  flex-wrap: wrap;
  position: relative;
}
.ecosystem-pillar {
  flex: 1;
  min-width: 240px;
  max-width: 300px;
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 32px 24px;
  text-align: center;
  position: relative;
  transition: all var(--transition);
}
.ecosystem-pillar:hover {
  border-color: var(--accent-blue);
  transform: translateY(-4px);
  box-shadow: var(--shadow-card);
}
.pillar-icon {
  width: 64px; height: 64px;
  margin: 0 auto 16px;
  display: flex; align-items: center; justify-content: center;
  background: rgba(0,180,216,0.1);
  border-radius: 50%;
  font-size: 28px;
  color: var(--accent-blue);
}
.ecosystem-pillar h3 {
  font-size: 16px;
  font-weight: 700;
  margin-bottom: 12px;
  color: var(--text-primary);
}
.ecosystem-pillar p {
  font-size: 13px;
  color: var(--text-secondary);
  line-height: 1.6;
}
.ecosystem-connector {
  display: flex;
  align-items: center;
  justify-content: center;
  min-width: 60px;
  color: var(--accent-blue);
  font-size: 24px;
  opacity: 0.5;
}

/* Data lifecycle diagram */
.lifecycle-diagram {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0;
  flex-wrap: wrap;
  padding: 24px 0;
}
.lifecycle-step {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  padding: 16px;
  min-width: 100px;
}
.lifecycle-step-icon {
  width: 56px; height: 56px;
  border-radius: 50%;
  background: rgba(0,180,216,0.1);
  border: 2px solid var(--accent-blue);
  display: flex; align-items: center; justify-content: center;
  font-size: 22px;
  color: var(--accent-blue);
  margin-bottom: 10px;
}
.lifecycle-step-label {
  font-size: 12px;
  font-weight: 600;
  color: var(--text-secondary);
}
.lifecycle-arrow {
  font-size: 20px;
  color: var(--accent-blue);
  opacity: 0.4;
  padding: 0 4px;
}

/* --- Testimonials --- */
.testimonial-carousel {
  position: relative;
  overflow: hidden;
}
.testimonial-track {
  display: flex;
  transition: transform 0.5s ease;
}
.testimonial-card {
  min-width: 100%;
  padding: 40px;
  text-align: center;
}
.testimonial-card blockquote {
  font-size: 20px;
  font-style: italic;
  color: var(--text-primary);
  line-height: 1.7;
  max-width: 700px;
  margin: 0 auto 20px;
}
.testimonial-card cite {
  font-size: 14px;
  color: var(--accent-blue);
  font-style: normal;
  font-weight: 600;
}
.carousel-dots {
  display: flex;
  justify-content: center;
  gap: 8px;
  margin-top: 24px;
}
.carousel-dot {
  width: 10px; height: 10px;
  border-radius: 50%;
  background: var(--border-color);
  border: none;
  cursor: pointer;
  transition: all var(--transition);
}
.carousel-dot.active {
  background: var(--accent-blue);
  width: 28px;
  border-radius: var(--radius-full);
}

/* --- Culture / CTA Sections --- */
.cta-section {
  text-align: center;
  padding: var(--section-pad) 0;
}
.cta-section h2 { margin-bottom: 16px; }
.cta-section p {
  max-width: 600px;
  margin: 0 auto 32px;
  color: var(--text-secondary);
  font-size: 16px;
  line-height: 1.7;
}

/* Renewables CTA */
.renewables-cta {
  background: linear-gradient(135deg, #0D1B2A 0%, #1B2838 50%, #0D2818 100%);
  text-align: center;
  padding: var(--section-pad) 0;
  position: relative;
  overflow: hidden;
}
.renewables-cta::before {
  content: '';
  position: absolute;
  top: -100px; right: -100px;
  width: 300px; height: 300px;
  background: radial-gradient(circle, rgba(108,194,74,0.1) 0%, transparent 70%);
  pointer-events: none;
}

/* --- Security Features --- */
.feature-list {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
  gap: 20px;
}
.feature-item {
  display: flex;
  gap: 16px;
  padding: 24px;
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  transition: all var(--transition);
}
.feature-item:hover {
  border-color: var(--accent-blue);
  transform: translateX(4px);
}
.feature-item-icon {
  width: 40px; height: 40px;
  display: flex; align-items: center; justify-content: center;
  background: rgba(0,180,216,0.1);
  border-radius: var(--radius-sm);
  color: var(--accent-blue);
  font-size: 18px;
  flex-shrink: 0;
}
.feature-item h4 {
  font-size: 15px;
  font-weight: 700;
  margin-bottom: 6px;
}
.feature-item p {
  font-size: 13px;
  color: var(--text-secondary);
  line-height: 1.5;
}

/* --- ETL Benefits --- */
.benefits-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 20px;
}
.benefit-card {
  display: flex;
  gap: 14px;
  align-items: flex-start;
  padding: 24px;
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  transition: all var(--transition);
}
.benefit-card:hover {
  border-color: var(--accent-green);
}
.benefit-check {
  width: 28px; height: 28px;
  display: flex; align-items: center; justify-content: center;
  background: rgba(108,194,74,0.15);
  border-radius: 50%;
  color: var(--accent-green);
  font-size: 14px;
  flex-shrink: 0;
  margin-top: 2px;
}
.benefit-card h4 {
  font-size: 15px;
  font-weight: 700;
  margin-bottom: 4px;
}
.benefit-card p {
  font-size: 13px;
  color: var(--text-secondary);
  line-height: 1.5;
}

/* --- Demo Form --- */
.demo-section {
  padding: 120px 0 var(--section-pad);
  min-height: 100vh;
}
.demo-form-container {
  max-width: 640px;
  margin: 0 auto;
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 48px;
}
.demo-form-container h2 {
  font-size: 28px;
  font-weight: 800;
  margin-bottom: 8px;
  letter-spacing: -0.5px;
}
.demo-form-container .form-desc {
  font-size: 14px;
  color: var(--text-secondary);
  margin-bottom: 32px;
  line-height: 1.6;
}
.form-row { display: flex; gap: 16px; margin-bottom: 20px; }
.form-group {
  flex: 1;
  display: flex;
  flex-direction: column;
}
.form-group label {
  font-size: 13px;
  font-weight: 600;
  color: var(--text-secondary);
  margin-bottom: 6px;
}
.form-group label .required { color: var(--accent-blue); }
.form-group input,
.form-group select,
.form-group textarea {
  padding: 12px 16px;
  background: var(--bg-input);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  color: var(--text-primary);
  font-size: 14px;
  font-family: inherit;
  transition: border-color var(--transition);
  outline: none;
}
.form-group input:focus,
.form-group select:focus,
.form-group textarea:focus {
  border-color: var(--accent-blue);
  box-shadow: 0 0 0 3px rgba(0,180,216,0.1);
}
.form-group input.error,
.form-group select.error,
.form-group textarea.error {
  border-color: #ef4444;
}
.form-group .error-msg {
  font-size: 12px;
  color: #ef4444;
  margin-top: 4px;
  display: none;
}
.form-group input.error ~ .error-msg { display: block; }
.form-group textarea { resize: vertical; min-height: 100px; }
.form-submit {
  margin-top: 12px;
  width: 100%;
  padding: 14px;
  background: var(--accent-gradient);
  color: #fff;
  font-size: 16px;
  font-weight: 700;
  border: none;
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: all var(--transition);
}
.form-submit:hover { box-shadow: 0 4px 16px rgba(0,180,216,0.4); transform: translateY(-1px); }
.form-success {
  display: none;
  text-align: center;
  padding: 40px;
}
.form-success.show { display: block; }
.form-success svg { margin-bottom: 16px; }
.form-success h3 { font-size: 24px; margin-bottom: 8px; }
.form-success p { color: var(--text-secondary); font-size: 14px; }

/* --- Support Contact --- */
.support-section { padding: var(--section-pad) 0; }
.support-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}
.support-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 32px;
  text-align: center;
  transition: all var(--transition);
}
.support-card:hover { border-color: var(--accent-blue); }
.support-card h4 {
  font-size: 16px;
  font-weight: 700;
  margin-bottom: 8px;
}
.support-card p {
  font-size: 14px;
  color: var(--text-secondary);
  line-height: 1.5;
}

/* --- Cookie Banner --- */
.cookie-banner {
  position: fixed;
  bottom: 0; left: 0; right: 0;
  z-index: 9999;
  background: var(--bg-card);
  border-top: 1px solid var(--border-color);
  padding: 20px 0;
  box-shadow: 0 -4px 24px rgba(0,0,0,0.3);
  transition: transform 0.4s ease;
}
.cookie-banner.hidden {
  transform: translateY(100%);
  pointer-events: none;
}
.cookie-inner {
  max-width: var(--container);
  margin: 0 auto;
  padding: 0 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
}
.cookie-inner p {
  font-size: 14px;
  color: var(--text-secondary);
  line-height: 1.5;
}
.cookie-actions { display: flex; gap: 12px; flex-shrink: 0; }
.cookie-accept {
  padding: 8px 24px;
  background: var(--accent-gradient);
  color: #fff;
  font-size: 13px;
  font-weight: 600;
  border: none;
  border-radius: var(--radius-full);
  cursor: pointer;
  transition: all var(--transition);
}
.cookie-accept:hover { box-shadow: 0 2px 12px rgba(0,180,216,0.4); }
.cookie-decline {
  padding: 8px 24px;
  background: transparent;
  color: var(--text-secondary);
  font-size: 13px;
  font-weight: 600;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-full);
  cursor: pointer;
  transition: all var(--transition);
}
.cookie-decline:hover { border-color: var(--text-secondary); color: var(--text-primary); }

/* --- Footer --- */
.site-footer {
  background: #0A1520;
  border-top: 1px solid var(--border-color);
  padding: 60px 0 32px;
}
.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr 1fr;
  gap: 32px;
  margin-bottom: 48px;
}
.footer-brand .logo { margin-bottom: 12px; }
.footer-brand p {
  font-size: 13px;
  color: var(--text-muted);
  line-height: 1.6;
  max-width: 280px;
}
.footer-col h5 {
  font-size: 13px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--text-primary);
  margin-bottom: 16px;
}
.footer-col ul { list-style: none; }
.footer-col li { margin-bottom: 8px; }
.footer-col a {
  font-size: 13px;
  color: var(--text-muted);
  transition: color var(--transition);
}
.footer-col a:hover { color: var(--accent-blue); }
.footer-bottom {
  border-top: 1px solid var(--border-color);
  padding-top: 24px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 16px;
}
.footer-bottom p {
  font-size: 12px;
  color: var(--text-muted);
}
.footer-logins {
  display: flex;
  gap: 12px;
}
.footer-logins a {
  font-size: 12px;
  color: var(--text-muted);
  padding: 4px 12px;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-full);
  transition: all var(--transition);
}
.footer-logins a:hover { border-color: var(--accent-blue); color: var(--accent-blue); }

/* --- Platform Benefits --- */
.benefits-list {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 24px;
}
.benefit-item {
  text-align: center;
  padding: 32px 20px;
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  transition: all var(--transition);
}
.benefit-item:hover {
  border-color: var(--accent-blue);
  transform: translateY(-4px);
}
.benefit-item-icon {
  width: 52px; height: 52px;
  margin: 0 auto 16px;
  display: flex; align-items: center; justify-content: center;
  background: rgba(0,180,216,0.1);
  border-radius: 50%;
  font-size: 24px;
  color: var(--accent-blue);
}
.benefit-item h4 {
  font-size: 16px;
  font-weight: 700;
  margin-bottom: 8px;
}
.benefit-item p {
  font-size: 13px;
  color: var(--text-secondary);
  line-height: 1.5;
}

/* --- Integration page specific --- */
.integration-content {
  max-width: 800px;
}
.integration-content h3 {
  font-size: 20px;
  font-weight: 700;
  margin-bottom: 12px;
}
.integration-content p {
  font-size: 15px;
  color: var(--text-secondary);
  line-height: 1.7;
  margin-bottom: 24px;
}

/* --- Responsive --- */
@media (max-width: 1024px) {
  .hero h1 { font-size: 40px; }
  .section-title { font-size: 30px; }
  .card-grid { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: 1fr 1fr 1fr; }
  .footer-brand { grid-column: 1 / -1; }
  .ecosystem-connector { display: none; }
  .ecosystem-diagram { gap: 20px; }
}

@media (max-width: 768px) {
  :root { --section-pad: 60px; }
  .hero h1 { font-size: 32px; }
  .hero p { font-size: 16px; }
  .section-title { font-size: 26px; }
  .card-grid { grid-template-columns: 1fr; }
  .stats-row { grid-template-columns: 1fr; gap: 40px; }
  .benefits-list { grid-template-columns: repeat(2, 1fr); }
  .benefits-grid { grid-template-columns: 1fr; }
  .feature-list { grid-template-columns: 1fr; }
  .support-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .featured-banner { flex-direction: column; text-align: center; padding: 32px 24px; }
  .form-row { flex-direction: column; gap: 20px; }
  .demo-form-container { padding: 32px 24px; }
  .cookie-inner { flex-direction: column; text-align: center; }

  /* Mobile nav */
  .nav { display: none; }
  .nav.open {
    display: flex;
    flex-direction: column;
    position: absolute;
    top: 72px; left: 0; right: 0;
    background: var(--bg-primary);
    border-bottom: 1px solid var(--border-color);
    padding: 16px 24px;
    gap: 4px;
  }
  .nav.open .nav-dropdown .dropdown-menu {
    position: static;
    opacity: 1;
    visibility: visible;
    transform: none;
    box-shadow: none;
    border: none;
    background: rgba(255,255,255,0.03);
    margin-top: 4px;
  }
  .menu-toggle { display: block; }

  .ecosystem-diagram { flex-direction: column; align-items: center; }
  .ecosystem-pillar { max-width: 100%; }
  .lifecycle-diagram { gap: 0; justify-content: center; }
  .lifecycle-arrow { font-size: 14px; }
  .lifecycle-step { min-width: 70px; padding: 8px; }
  .lifecycle-step-icon { width: 40px; height: 40px; font-size: 16px; }
  .lifecycle-step-label { font-size: 10px; }
  .timeline-item { flex-direction: column; gap: 8px; }
  .timeline-duration { text-align: left; min-width: auto; }
  .testimonial-card { padding: 24px; }
  .testimonial-card blockquote { font-size: 16px; }
}

@media (max-width: 480px) {
  .hero h1 { font-size: 28px; }
  .hero-actions { flex-direction: column; }
  .benefits-list { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr; }
  .footer-bottom { flex-direction: column; text-align: center; }
  .footer-logins { justify-content: center; flex-wrap: wrap; }
}
